// === Tab: Firefly ===
class Firefly{
	constructor(){
		this.light = color(255,255,0)
		this.dim = color(55)
		this.t = 0
		this.x = width/2
		this.y = height/2
		this.a = map(sin(this.t),-1,1,0,1)
		this.dF = random(1000)
		this.facing = map(noise(this.dF),0,1,-TAU,TAU)
		this.size = random(0.1,0.25)
		this.speed = random(0.5,2) * this.size*4
	}

	update(){
		this.t += this.speed * 0.1
		this.a = map(sin(this.t),-1,1,0,1)
		this.x += this.speed * 2 * cos(this.facing)
		this.y += this.speed * 2 * sin(this.facing)
		if(this.x > width + 50){
			this.x = -50
		}else if(this.x < -50){
			this.x = width + 50
		}
		if(this.y > height + 50){
			this.y = -50
		}else if(this.y < -50){
			this.y = height + 50
		}
		this.dF += 0.0025
		this.facing = map(noise(this.dF),0,1,-TAU,TAU)
	}

	display(){		
		push()
		translate(this.x,this.y)
		rotate(this.facing)
		scale(this.size)
		stroke(35)
		strokeWeight(2)
		line(0,0,30*cos(PI/6),30*sin(PI/6))
		line(0,0,30*cos(-PI/6),30*sin(-PI/6))
		strokeWeight(5)
		point(30*cos(PI/6),30*sin(PI/6))
		point(30*cos(-PI/6),30*sin(-PI/6))
		noStroke()
		fill(35)
		ellipse(-5,0,40,40)
		fill(this.light)
		ellipse(-50,0,100,50)
		fill(30)
		stroke(30)
		rotate(-this.a)
		ellipse(-50,0,100,50)
		rotate(2*this.a)
		ellipse(-50,0,100,50)
		pop()
	}
}

