let fireflies = []

function setup() {
	createCanvas(windowWidth, windowHeight);
	for(let i = 0; i < 10; i++){
		fireflies.push(new Firefly())
	}

}

function draw() {
	background(20,15,20);
	fireflies.forEach(firefly => {
		firefly.update()
		firefly.display()
	})
}
